DefinitionA caching layer for LLM responses stores previously generated outputs so repeated or similar queries can be served instantly without calling the model again.Why it is usedReduces latency (faster responses)Saves API cost (fewer LLM calls)Improves scalabilityHandles repeated queries efficientlyHow it works (step-by-step)User sends queryGenerate cache key (e.g., hash of query)Check if response exists in cacheIf yes → return cached resultIf no → call LLMStore new response in cacheReturn resultKey componentsCache store: In-memory (dict, Redis)Cache key: Unique identifier for queryTTL (time-to-live): Expiry timeSerialization: Store structured responsesBasic implementation (Python)import time
import hashlib

# -------- Simple Cache -------- #

class Cache:
    def __init__(self, ttl=60):
        self.store = {}
        self.ttl = ttl

    def _is_expired(self, timestamp):
        return (time.time() - timestamp) > self.ttl

    def get(self, key):
        if key in self.store:
            value, timestamp = self.store[key]
            if not self._is_expired(timestamp):
                return value
            else:
                del self.store[key]
        return None

    def set(self, key, value):
        self.store[key] = (value, time.time())

# -------- LLM Mock -------- #

def call_llm(prompt):
    return f"LLM response for: {prompt}"

# -------- Cache Layer -------- #

cache = Cache(ttl=120)

def generate_cache_key(query):
    return hashlib.md5(query.encode()).hexdigest()

def get_response(query):
    key = generate_cache_key(query)

    # Check cache
    cached = cache.get(key)
    if cached:
        print("Cache hit")
        return cached

    # Call LLM
    print("Cache miss → calling LLM")
    response = call_llm(query)

    # Store in cache
    cache.set(key, response)

    return response

# -------- Example -------- #

print(get_response("What is semantic search?"))
print(get_response("What is semantic search?"))  # Cached
