DefinitionMetrics tracking in LLM systems means measuring key signals like accuracy, latency, and cost for every request to evaluate performance and optimize the system.Why it is usedMonitor system quality and performanceIdentify bottlenecks and failuresOptimize cost vs accuracy trade-offsEnable A/B testing and improvementsHow it works (step-by-step)Capture request start timeCall LLM or pipelineMeasure latency (end - start)Compute cost (based on tokens or pricing)Evaluate accuracy (via ground truth or judge)Store metrics for analysisKey componentsLatency tracker: Measures response timeCost calculator: Based on token usageAccuracy evaluator: Ground truth or LLM judgeMetrics store: Logs aggregated dataBasic implementation (Python)import time

# -------- Mock LLM -------- #

def call_llm(prompt):
    time.sleep(0.1)  # simulate latency
    return {
        "response": f"Answer for: {prompt}",
        "tokens": 100  # simulated token usage
    }

# -------- Cost Function -------- #

def calculate_cost(tokens, price_per_1k=0.002):
    return (tokens / 1000) * price_per_1k

# -------- Accuracy Function -------- #

def evaluate_accuracy(prediction, ground_truth):
    return int(ground_truth.lower() in prediction.lower())

# -------- Metrics Tracker -------- #

class MetricsTracker:
    def __init__(self):
        self.data = []

    def log(self, latency, cost, accuracy):
        self.data.append({
            "latency": latency,
            "cost": cost,
            "accuracy": accuracy
        })

    def summary(self):
        n = len(self.data)
        return {
            "avg_latency": sum(d["latency"] for d in self.data) / n,
            "avg_cost": sum(d["cost"] for d in self.data) / n,
            "accuracy": sum(d["accuracy"] for d in self.data) / n
        }

# -------- Pipeline -------- #

tracker = MetricsTracker()

def process(query, ground_truth):
    start = time.time()

    result = call_llm(query)

    latency = time.time() - start
    cost = calculate_cost(result["tokens"])
    accuracy = evaluate_accuracy(result["response"], ground_truth)

    tracker.log(latency, cost, accuracy)

    return result["response"]

# -------- Example -------- #

process("What is semantic search?", "semantic search")
process("Explain RAG", "retrieval")

print(tracker.summary())
